    def find_parent(
        self,
        name: _FindMethodName = None,
        attrs: Optional[_StrainableAttributes] = None,
        **kwargs: _StrainableAttribute,
    ) -> _AtMostOneTag:
        
        r = None
        results = self.find_parents(
            name, attrs, 1, _stacklevel=3, **kwargs
        )
        if results:
            r = results[0]
        return r

